  'Name a trigger': { ar: 'سمِّ محفزاً', pt: 'Nomeie um gatilho', es: 'Nombra un disparador', de: 'Nenne einen Auslöser', fr: 'Nomme un déclencheur', it: 'Dai un nome a un trigger' },
  'My if-then plan': { ar: 'خطة "إذا-فإن" الخاصة بي', pt: 'Meu plano se-então', es: 'Mi plan si-entonces', de: 'Mein Wenn-dann-Plan', fr: 'Mon plan si-alors', it: 'Il mio piano se-allora' },
  'IF (trigger)': { ar: 'إذا (محفز)', pt: 'SE (gatilho)', es: 'SI (disparador)', de: 'WENN (Auslöser)', fr: 'SI (déclencheur)', it: 'SE (trigger)' },
  'THEN (action)': { ar: 'فإن (فعل)', pt: 'ENTÃO (ação)', es: 'ENTONCES (acción)', de: 'DANN (Handlung)', fr: 'ALORS (action)', it: 'ALLORA (azione)' },
