  'Log a check-in now': { ar: 'سجّل حالتك الآن', pt: 'Faça um check-in agora', es: 'Haz un check-in ahora', de: 'Jetzt ein Check-in', fr: 'Fais un check-in maintenant', it: 'Fai un check-in ora' },
  'Turn on the daily gate': { ar: 'فعّل البوابة اليومية', pt: 'Ativar o portão diário', es: 'Activar la puerta diaria', de: 'Tägliches Gate aktivieren', fr: 'Activer la porte quotidienne', it: 'Attiva il portale giornaliero' },
  'Copy the blocklist': { ar: 'نسخ قائمة الحظر', pt: 'Copiar a lista de bloqueio', es: 'Copiar la lista de bloqueo', de: 'Blockliste kopieren', fr: 'Copier la liste de blocage', it: 'Copia la lista di blocco' },
  'Open replacement activities': { ar: 'افتح الأنشطة البديلة', pt: 'Abrir atividades substitutas', es: 'Abrir actividades de reemplazo', de: 'Ersatzaktivitäten öffnen', fr: 'Ouvrir les activités de remplacement', it: 'Apri le attività sostitutive' },
  'Start a 10-minute timer': { ar: 'شغّل مؤقت 10 دقائق', pt: 'Iniciar timer de 10 minutos', es: 'Iniciar temporizador de 10 minutos', de: '10-Minuten-Timer starten', fr: 'Lancer un minuteur de 10 min', it: 'Avvia un timer di 10 minuti' },
  'Write it here…': { ar: 'اكتب هنا…', pt: 'Escreva aqui…', es: 'Escribe aquí…', de: 'Schreibe hier…', fr: 'Écris ici…', it: 'Scrivi qui…' },
  'Your answers stay on this device.': { ar: 'إجاباتك تبقى على هذا الجهاز.', pt: 'Suas respostas ficam neste aparelho.', es: 'Tus respuestas quedan en este dispositivo.', de: 'Deine Antworten bleiben auf diesem Gerät.', fr: 'Tes réponses restent sur cet appareil.', it: 'Le tue risposte restano su questo dispositivo.' },
  'Pick up to 3': { ar: 'اختر حتى 3', pt: 'Escolha até 3', es: 'Elige hasta 3', de: 'Wähle bis zu 3', fr: 'Choisis-en jusqu\'à 3', it: 'Scegline fino a 3' },
  'Open your crisis plan': { ar: 'افتح خطة الأزمة', pt: 'Abrir plano de crise', es: 'Abrir plan de crisis', de: 'Krisenplan öffnen', fr: 'Ouvrir le plan de crise', it: 'Apri il piano di crisi' },
  'Try the panic flow': { ar: 'جرّب تدفق الذعر', pt: 'Experimentar o fluxo de pânico', es: 'Probar el flujo de pánico', de: 'Den Panik-Flow ausprobieren', fr: 'Essayer le flux de panique', it: 'Prova il flusso di panico' },
  'I commit: slip → log it → continue': { ar: 'ألتزم: انزلاق ← تسجيل ← استمرار', pt: 'Me comprometo: deslize → registre → continue', es: 'Me comprometo: desliz → regístralo → continúa', de: 'Ich verpflichte mich: Rückfall → protokollieren → weiter', fr: 'Je m\'engage : faux pas → enregistre → continue', it: 'Mi impegno: passo falso → registralo → continua' },
  'Situation': { ar: 'الموقف', pt: 'Situação', es: 'Situación', de: 'Situation', fr: 'Situation', it: 'Situazione' },
  'Automatic thought': { ar: 'الفكرة التلقائية', pt: 'Pensamento automático', es: 'Pensamiento automático', de: 'Automatischer Gedanke', fr: 'Pensée automatique', it: 'Pensiero automatico' },
  'Evidence against it': { ar: 'الدليل ضدها', pt: 'Evidência contra', es: 'Evidencia en contra', de: 'Gegenbeweis', fr: 'Preuve contraire', it: 'Prove contrarie' },
  'Balanced thought': { ar: 'الفكرة المتوازنة', pt: 'Pensamento equilibrado', es: 'Pensamiento equilibrado', de: 'Ausgewogener Gedanke', fr: 'Pensée équilibrée', it: 'Pensiero equilibrato' },
  'Check the thought': { ar: 'افحص الفكرة', pt: 'Examine o pensamento', es: 'Examina el pensamiento', de: 'Den Gedanken prüfen', fr: 'Examine la pensée', it: 'Esamina il pensiero' },
  '3 things I will do with my time': { ar: '3 أشياء سأفعلها بوقتي', pt: '3 coisas que farei com meu tempo', es: '3 cosas que haré con mi tiempo', de: '3 Dinge, die ich mit meiner Zeit mache', fr: '3 choses que je ferai de mon temps', it: '3 cose che farò del mio tempo' },
